 protected void attachBaseContext(Context c){super.attachBaseContext(AppLanguage.wrap(c));}
 public void onCreate(Bundle state){super.onCreate(state);palette=AppPalette.of(this);uri=getIntent().getData();if(uri==null){finish();return;}name=getIntent().getStringExtra("name");if(name==null)name="Seeky";getWindow().setStatusBarColor(palette.bg);getWindow().setNavigationBarColor(palette.bg);
 LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setFitsSystemWindows(true);root.setBackgroundColor(palette.bg);if(Build.VERSION.SDK_INT>=35)root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets bars=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return i;});
 LinearLayout head=new LinearLayout(this);head.addView(button("‹",this::finish));TextView title=text("",18);title.setText(name);title.setSingleLine();title.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));head.addView(button("⋯",this::menu));root.addView(head);
 stage=new FrameLayout(this);stage.setBackgroundColor(0xff10141d);boolean isVideo=MediaFormats.kind(name,getIntent().getType()==null?"":getIntent().getType()).equals("video");if(isVideo){video=new TextureView(this);video.setSurfaceTextureListener(this);stage.addView(video,new FrameLayout.LayoutParams(-1,-1));}else{LinearLayout cover=new LinearLayout(this);cover.setOrientation(1);cover.setGravity(Gravity.CENTER);Icons icon=new Icons(this,"audio",palette.accent);cover.addView(icon,new LinearLayout.LayoutParams(dp(96),dp(96)));TextView brand=text("SEEKY MUSIC",13);brand.setTextColor(0xffedf2fa);cover.addView(brand);stage.addView(cover,new FrameLayout.LayoutParams(-1,-1));}root.addView(stage,new LinearLayout.LayoutParams(-1,0,1));
 status=text("A preparar…",12);status.setTextColor(palette.muted);root.addView(status);time=text("00:00 / 00:00",13);time.setGravity(Gravity.CENTER);root.addView(time);seek=new SeekBar(this);seek.setMax(1000);seek.setProgressTintList(android.content.res.ColorStateList.valueOf(palette.accent));root.addView(seek);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int value,boolean user){}public void onStartTrackingTouch(SeekBar b){seeking=true;}public void onStopTrackingTouch(SeekBar b){if(service!=null)service.seek((long)service.duration()*b.getProgress()/1000);seeking=false;}});
 LinearLayout controls=new LinearLayout(this);controls.addView(button("−10 s",()->{if(service!=null)service.skip(-10000);}),new LinearLayout.LayoutParams(0,dp(64),1));play=button("Reproduzir",()->command(service!=null&&service.playing?MediaPlaybackService.PAUSE:MediaPlaybackService.PLAY));controls.addView(play,new LinearLayout.LayoutParams(0,dp(64),2));controls.addView(button("+10 s",()->{if(service!=null)service.skip(10000);}),new LinearLayout.LayoutParams(0,dp(64),1));root.addView(controls);
 TextView signature=text("Haidoy Carlos Mautempo",10);signature.setGravity(Gravity.CENTER);signature.setTextColor(palette.muted);root.addView(signature);setContentView(root);
 try{startForegroundService(new Intent(this,MediaPlaybackService.class).setAction(MediaPlaybackService.OPEN).setData(uri).putExtra("name",name));}catch(Exception e){status.setText(AppLanguage.text(this,"Não foi possível reproduzir."));AppDiagnostics.record(this,"media-start",e);}
 }
 void command(String action){try{startForegroundService(new Intent(this,MediaPlaybackService.class).setAction(action));}catch(Exception e){AppDiagnostics.record(this,"media-command",e);}}
 void menu(){new UiDialog.Builder(this).setTitle("Reprodução").setItems(new String[]{"Velocidade","Repetir","Abrir fora","Parar reprodução","Capítulos e títulos","Temporizador de sono"},(d,n)->{if(n==0)new UiDialog.Builder(this).setTitle("Velocidade").setItems(new String[]{"0.75×","1×","1.25×","1.5×","2×"},(x,p)->{if(service!=null)service.speed(new float[]{.75f,1,1.25f,1.5f,2}[p]);}).show();else if(n==1){if(service!=null)service.repeat=!service.repeat;}else if(n==2){try{Catalog.Entry e=new Catalog.Entry();e.uri=uri.toString();Uri shared=StorageAccess.shareUri(this,e);Intent outside=new Intent(Intent.ACTION_VIEW).setDataAndType(shared,MediaFormats.mime(name,getIntent().getType())).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);outside.setClipData(ClipData.newRawUri(name,shared));startActivity(Intent.createChooser(outside,AppLanguage.text(this,"Abrir fora")));}catch(Exception e){Toast.makeText(this,AppLanguage.text(this,"Formato indisponível."),Toast.LENGTH_SHORT).show();}}else if(n==4)NarrationIndex.show(this);else if(n==5)NarrationIndex.sleep(this);else{command(MediaPlaybackService.STOP);finish();}}).show();}
 final Runnable tick=new Runnable(){public void run(){if(service!=null){if(!seeking)seek.setProgress(service.duration()==0?0:(int)(1000L*service.position()/service.duration()));time.setText(ReaderActivity.clock(service.position())+" / "+ReaderActivity.clock(service.duration()));play.setText(AppLanguage.text(MediaActivity.this,service.playing?"Pausar":"Reproduzir"));status.setText(AppLanguage.text(MediaActivity.this,!service.error.isEmpty()?service.error:!service.ready?"A preparar…":service.repeat?"Repetir activado":"Reprodução em segundo plano"));fitVideo();}handler.postDelayed(this,500);}};
 protected void onStart(){super.onStart();if(workspaceEpoch!=WorkspaceEpoch.value){finish();return;}bound=bindService(new Intent(this,MediaPlaybackService.class),connection,BIND_AUTO_CREATE);}
 protected void onStop(){handler.removeCallbacks(tick);if(service!=null)service.attach(null);if(bound){unbindService(connection);bound=false;}service=null;super.onStop();}
 protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(surface!=null){surface.release();surface=null;}super.onDestroy();}
 void fitVideo(){if(video==null||service==null||service.player==null||!service.ready)return;int w=service.player.getVideoWidth(),h=service.player.getVideoHeight();if(w<1||h<1||video.getWidth()<1||video.getHeight()<1)return;float vw=video.getWidth(),vh=video.getHeight(),scale=Math.min(vw/w,vh/h);Matrix m=new Matrix();m.setScale(w*scale/vw,h*scale/vh,vw/2,vh/2);video.setTransform(m);}
 public void onSurfaceTextureAvailable(SurfaceTexture texture,int w,int h){surface=new Surface(texture);if(service!=null)service.attach(surface);}
 public void onSurfaceTextureSizeChanged(SurfaceTexture texture,int w,int h){fitVideo();}
 public boolean onSurfaceTextureDestroyed(SurfaceTexture texture){if(service!=null)service.attach(null);if(surface!=null){surface.release();surface=null;}return true;}
 public void onSurfaceTextureUpdated(SurfaceTexture texture){}
